fn tokenize(sec: &str) -> (Vec<Tk>, bool) {
    let cs: Vec<char> = sec.chars().collect();
    let mut i = 0; let mut t = Vec::new(); let mut date = false;
    while i < cs.len() {
        let c = cs[i];
