            '[' => { while i < cs.len() && cs[i] != ']' { i += 1; } i += 1; }
            '_' => { t.push(Tk::Lit(" ".into())); i += 2; }
            '*' => { i += 2; }
            '0' | '#' | '?' => { t.push(Tk::Dig(c)); i += 1; }
            ',' => { t.push(Tk::Comma); i += 1; }
            '.' => {
