                } else { t.push(Tk::Dot); i += 1; }
            }
            '%' => { t.push(Tk::Pct); i += 1; }
            'E' | 'e' if i + 1 < cs.len() && (cs[i + 1] == '+' || cs[i + 1] == '-') => { t.push(Tk::Exp(cs[i + 1] == '+')); i += 2; }
