    }
    // parse (range, crit) pairs from args
    fn parse_pairs(&self, args: &[Node], cx: Cx) -> Result<(Vec<Rg>, Vec<Crit>), Er> {
        let mut rs = Vec::new(); let mut cs = Vec::new();
