                    Some(i) => if vert { Ok(Arg::R(rg.0, rg.1 + i, rg.2, rg.1 + i, rg.4)) } else { Ok(Arg::R(rg.0, rg.1, rg.2 + i, rg.3, rg.2 + i)) },
                    None => if has(3) { Ok(self.arg(&args[3], cx)) } else { Err(Er::Na) },
