pool=[]
for f in fs:
    wb=openpyxl.load_workbook(f)
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value,str) and c.value.startswith('='): pool.append(c.value)
refre=re.compile(r'(?<![A-Za-z!$])\$?([A-F])\$?(\d{1,2})(?![\d(])')
numre=re.compile(r'(?<![A-Za-z$\d.])(\d+\.?\d*)(?![\d(A-Za-z!:])')
wraps=['ROUND({},1)','LEN({})','{}&"x"','-({})','ABS({})','IF(ISERROR({}),"e",{})','IFERROR({},0)','TEXT({},"0.00")','({})*2','NOT({})','UPPER({})','INT({})','{}+1','{}>5','IFNA({},"n")','MAX({},0)','VALUE({})','N({})','SUM({},1)']
def mutate(f):
    f=f
    k=random.random()
    if k<0.5:
        f=refre.sub(lambda m: m.group(0) if random.random()<0.6 else '%s%d'%(random.choice('ABCDEF'),random.randint(1,18)), f)
    if random.random()<0.4:
        f=numre.sub(lambda m: m.group(0) if random.random()<0.6 else random.choice(['0','1','2','3','-1','0.5','100','7','10','12']), f)
    if random.random()<0.35:
        f='='+random.choice(wraps).format(f[1:],f[1:])
    return f
for k,a in enumerate(fs):
    wb=openpyxl.load_workbook(a)
    ws=wb['Calc']
    for r in range(1,41):
        for col in ('H','I','J'):
            ws['%s%d'%(col,r)]=mutate(random.choice(pool))
    wb.save('/tmp/fz/in/m%s_%02d.xlsx'%(sys.argv[1],k))
E
